Thread t = new Thread(() -> System.out.println("Running")); // NEW
t.start(); // Transitions to RUNNABLE
// Locks -> BLOCKED | wait() -> WAITING | sleep(1000) -> TIMED_WAITING
// Execution finishes -> TERMINATED

synchronized(obj) {
    obj.wait(); // Releases monitor lock temporarily
    Thread.sleep(1000); // Holds monitor lock during sleep
}

ExecutorService executor = Executors.newFixedThreadPool(2);

// execute() - Fire and forget (Runnable, no return value)
executor.execute(() -> System.out.println("Fire and forget"));

// submit() - Returns Future<T> (Callable/Runnable, captures exceptions)
Future<String> future = executor.submit(() -> "Result from Callable");
String res = future.get(); // blocks until complete

import java.util.concurrent.CompletableFuture;

CompletableFuture.supplyAsync(() -> 10)
    .thenApply(val -> val * 2)
    .thenAccept(res -> System.out.println("Final: " + res))
    .exceptionally(ex -> { System.out.println(ex.getMessage()); return null; });

